def build_gpt_oss_parser(tokenizer: Any, *, model_id: str) -> HFResponseParser:
    if tokenizer_supports_response_parsing(tokenizer):
        return TokenizerNativeResponseParser(tokenizer)

    normalized_model_id = model_id.lower().replace("_", "-")
    if "gpt-oss" in normalized_model_id:
        return GptOssHarmonyResponseParser()

    return JsonEnvelopeToolCallParser()

def parse(
        self,
        response: HFGenerationResponse,
        *,
        fallback_call_id: str,
    ) -> AgentDecision:
        parsed_response = _parse_gpt_oss_harmony_response(response.raw_text)
        if parsed_response is not None:
            return normalize_parsed_response(
                parsed_response,
                fallback_call_id=fallback_call_id,
            )

        stripped = response.text.strip()
        if stripped:
            return FinalResponseDecision(text=stripped)
        raise InvalidModelOutputError("Model returned empty output")

def _parse_gpt_oss_harmony_response(raw_text: str) -> dict[str, Any] | None:
    if not raw_text.strip():
        return None

    tool_calls: list[dict[str, Any]] = []
    for match in _GPT_OSS_TOOL_CALL_PATTERN.finditer(raw_text):
        header = match.group("header")
        tool_match = re.search(r"to=functions\.([A-Za-z0-9_.-]+)", header)
        if tool_match is None:
            raise InvalidModelOutputError("GPT-OSS tool call output is missing a function target")
        arguments = normalize_tool_arguments(match.group("arguments").strip())
        tool_calls.append(
            {
                "type": "function",
                "function": {
                    "name": tool_match.group(1),
                    "arguments": arguments,
                },
            }
        )

    content_chunks = [
        match.group("content").strip()
        for match in _GPT_OSS_FINAL_MESSAGE_PATTERN.finditer(raw_text)
        if match.group("content").strip()
    ]
    content = "\n".join(content_chunks)

    if not tool_calls and not content:
        return None

    return {
        "role": "assistant",
        "content": content,
        "tool_calls": tool_calls,
    }

def next_action(
        self,
        *,
        history: RuntimeHistory,
        tools: Sequence[AgentToolSpec],
    ) -> AgentDecision:
        return self._delegate.next_action(history=history, tools=tools)

def normalize_parsed_response(
    parsed_response: Any,
    *,
    fallback_call_id: str,
) -> AgentDecision:
    if not isinstance(parsed_response, Mapping):
        raise InvalidModelOutputError("Parsed response must be an object")

    assistant_text = _normalize_assistant_text(parsed_response.get("content"))
    raw_tool_calls = parsed_response.get("tool_calls")
    if raw_tool_calls is not None:
        if not isinstance(raw_tool_calls, Sequence) or isinstance(raw_tool_calls, str):
            raise InvalidModelOutputError("Parsed tool calls must be a list")
        if len(raw_tool_calls) > 1:
            raise InvalidModelOutputError("Model returned multiple tool calls")
        if len(raw_tool_calls) == 1:
            return ToolCallDecision(
                call=_normalize_tool_call(
                    raw_tool_calls[0],
                    fallback_call_id=fallback_call_id,
                ),
                assistant_message=assistant_text or None,
            )

    if assistant_text:
        return FinalResponseDecision(text=assistant_text)

    raise InvalidModelOutputError("Parsed response produced neither assistant text nor tool call")

def _parse_response(
        self,
        response: HFGenerationResponse,
        *,
        state: HFChatTemplateAgentState,
    ) -> AgentDecision:
        fallback_call_id = f"call_{state.next_generated_call_index:06d}"
        if response.parsed_response is not None:
            return normalize_parsed_response(
                response.parsed_response,
                fallback_call_id=fallback_call_id,
            )
        return self._parser.parse(response, fallback_call_id=fallback_call_id)
